insert into public.journey_definitions(id,title,description) values
('ai_engineer','วิศวกร AI','เริ่มจาก Python ให้คล่อง แล้วค่อยต่อ API ของโมเดลภาษา ฝึก prompt และปิดท้ายด้วยระบบถามตอบจากเอกสาร (RAG)'),
('ml_engineer','วิศวกร Machine Learning','ทบทวนคณิตพื้นฐาน เทรนโมเดลแรกด้วย scikit-learn ต่อด้วย PyTorch แล้วฝึกวัดผลและนำโมเดลขึ้นใช้งาน'),
('data_scientist','นักวิทยาศาสตร์ข้อมูล','จัดการข้อมูลด้วย pandas และ SQL ทำกราฟที่เล่าเรื่องได้ ใช้สถิติตรวจข้อสรุป แล้วรวมเป็นรายงานหนึ่งชิ้น'),
('data_engineer','วิศวกรข้อมูล','SQL ขั้นสูงคือพื้นฐานหลัก ต่อด้วยการสร้าง ETL ออกแบบคลังข้อมูล และตั้งเวลารันงานให้เชื่อถือได้'),
('computer_vision_engineer','วิศวกร Computer Vision','เริ่มจัดการภาพด้วย OpenCV แล้วไปสู่การจำแนกภาพและตรวจจับวัตถุด้วย deep learning'),
('ai_researcher','นักวิจัย AI','ฝึกอ่านงานวิจัยอย่างมีระบบ ลองทำซ้ำผลลัพธ์ ออกแบบการทดลองที่ยุติธรรม และเขียนรายงานให้คนอื่นตรวจสอบได้'),
('robotics_engineer','วิศวกรหุ่นยนต์','ศึกษาแนวคิดของ ROS อ่านค่าเซนเซอร์ ลองในโปรแกรมจำลองก่อน แล้วค่อยสร้างหุ่นยนต์จริงเล็ก ๆ'),
('python','ภาษา Python','ภาษาที่อ่านง่ายและใช้ทั้งงาน AI ข้อมูล และสคริปต์อัตโนมัติ ฝึกจากพื้นฐาน → โครงสร้างข้อมูล → ไฟล์ → สคริปต์จริง'),
('prompt_engineering','การเขียน Prompt','เขียนคำสั่งให้ AI เข้าใจตรงกัน ใช้ตัวอย่างนำทาง ทดสอบเทียบผลอย่างเป็นระบบ และต่อหลายขั้นเป็นเวิร์กโฟลว์'),
('machine_learning','พื้นฐาน Machine Learning','เข้าใจว่าเครื่องเรียนรู้จากข้อมูลอย่างไร สร้างโมเดลแรก เตรียมข้อมูลให้ดี แล้วฝึกกับโจทย์จริงบน Kaggle'),
('math_for_ai','คณิตศาสตร์สำหรับ AI','คณิตที่ AI ใช้จริงมีสามเสาหลัก: พีชคณิตเชิงเส้น แคลคูลัส และความน่าจะเป็น แล้วฝึกแปลงสูตรเป็นโค้ด'),
('software_developer','นักพัฒนาซอฟต์แวร์','รากฐานของนักพัฒนา: เขียนโปรแกรมให้คล่อง คิดเป็นอัลกอริทึม ใช้ Git ทำงานร่วมกัน แล้วสร้างแอปจริง'),
('frontend_developer','นักพัฒนาฝั่งหน้าบ้าน','HTML คือโครง CSS คือหน้าตา JavaScript คือการโต้ตอบ แล้วต่อด้วย React และการรองรับทุกขนาดจอ'),
('backend_developer','นักพัฒนาฝั่งหลังบ้าน','สร้าง API ที่ถูกต้องตาม HTTP ออกแบบฐานข้อมูล ทำระบบยืนยันตัวตนอย่างปลอดภัย และเขียนเทสต์ป้องกันบั๊ก'),
('fullstack_developer','นักพัฒนาฟูลสแตก','เลือกเฟรมเวิร์กที่ทำได้ทั้งหน้าบ้านและหลังบ้าน เชื่อมฐานข้อมูล แล้วนำขึ้นออนไลน์ให้คนใช้จริง'),
('mobile_developer','นักพัฒนาแอปมือถือ','สร้างหน้าจอที่ใช้นิ้วกดง่าย จัดการสถานะของแอป เชื่อมกับ API และเตรียมแอปให้ทำงานได้แม้เน็ตไม่ดี'),
('devops_engineer','วิศวกร DevOps และคลาวด์','ใช้ Linux ให้คล่อง แพ็กแอปด้วย Docker ตั้ง CI/CD ให้ทดสอบและ deploy อัตโนมัติ แล้วเรียนบริการคลาวด์'),
('cybersecurity_specialist','ผู้เชี่ยวชาญความปลอดภัยไซเบอร์','เข้าใจเครือข่ายก่อน แล้วศึกษาช่องโหว่เว็บตาม OWASP ฝึกโจทย์ CTF ในสนามที่ได้รับอนุญาต และตรวจโค้ดหาจุดอ่อน'),
('qa_engineer','วิศวกรทดสอบซอฟต์แวร์','คิดแบบผู้ตรวจ: เขียน test case ให้ครอบคลุม ทำการทดสอบอัตโนมัติ รายงานบั๊กให้ทีมแก้ได้เร็ว'),
('embedded_developer','นักพัฒนาระบบฝังตัวและ IoT','เริ่มจากไฟกะพริบบน Arduino/ESP32 ฝึกภาษา C สำหรับบอร์ด แล้วส่งค่าเซนเซอร์ขึ้นอินเทอร์เน็ตด้วยโปรโตคอล IoT'),
('blockchain_developer','นักพัฒนาบล็อกเชน','เข้าใจกลไกบล็อกเชน เขียน smart contract ด้วย Solidity ศึกษาช่องโหว่ที่ทำให้เสียเงินจริง แล้วสร้าง dApp บน testnet'),
('ui_ux_designer','นักออกแบบ UI/UX','ใช้ Figma ให้คล่อง เข้าใจหลักการออกแบบที่ใช้งานง่าย ฝึกออกแบบทีละหน้าจอ และวิเคราะห์แอปจริง'),
('programming','การเขียนโปรแกรม','ทักษะพื้นฐานที่ใช้ได้ทุกภาษา: คิดเป็นขั้นตอน แก้โจทย์ อ่านเอกสาร และสร้างของเองโดยไม่พึ่งการคัดลอก'),
('javascript','ภาษา JavaScript','ภาษาของเว็บ: ฝึกพื้นฐานให้แน่น เข้าใจงาน asynchronous แล้วเพิ่มความปลอดภัยของชนิดข้อมูลด้วย TypeScript'),
('algorithms','อัลกอริทึมและโครงสร้างข้อมูล','ฝึกคิดอย่างมีโครงสร้าง: array/string → การเรียงและค้นหา → tree/graph พร้อมวิเคราะห์ความเร็วด้วย Big-O'),
('git_github','Git และ GitHub','จาก commit แรก สู่ branch, merge, Pull Request และการร่วมโปรเจกต์โอเพนซอร์ส'),
('sql_databases','SQL และฐานข้อมูล','ภาษามาตรฐานของฐานข้อมูล: SELECT ให้คล่อง JOIN หลายตาราง ออกแบบตารางที่ดี แล้วทำโปรเจกต์จริง'),
('linux_command_line','Linux และ Command Line','ทำงานผ่าน terminal ให้คล่อง ต่อคำสั่งด้วย pipe เขียน shell script อัตโนมัติ และเข้าเซิร์ฟเวอร์ด้วย SSH อย่างปลอดภัย'),
('cybersecurity_basics','พื้นฐานความปลอดภัยไซเบอร์','ความปลอดภัยเริ่มที่ตัวเรา: รหัสผ่านที่ดี รู้ทันการโจมตีที่พบบ่อย สร้างนิสัยปลอดภัย และลองโจทย์ CTF ง่าย ๆ'),
('game_developer','นักพัฒนาเกม','เขียนโปรแกรมให้แน่น (C++ เป็นภาษาหลักของ Unreal) ฝึกเอนจิน เข้าใจงาน 3D แล้วปิดด้วยมินิเกมที่เล่นจบได้'),
('game_designer','นักออกแบบเกม','ออกแบบประสบการณ์การเล่น: วิเคราะห์เกม ทำต้นแบบบนกระดาษ เขียนเอกสารออกแบบ ปรับสมดุล และทดสอบกับผู้เล่นจริง'),
('game_artist_3d','ศิลปินเกม 3 มิติ','สร้างโมเดลใน Blender คลี่ UV ลงเท็กซ์เจอร์ ทำงาน low-poly ที่เกมรันลื่น แล้วนำเข้าเอนจินให้ถูกต้อง'),
('game_artist_2d','ศิลปินเกม 2 มิติและพิกเซลอาร์ต','พื้นฐานพิกเซลอาร์ต แอนิเมชันสไปรต์ ออกแบบ tileset ต่อกันไร้รอย และวาด UI เกมที่อ่านง่าย'),
('technical_artist','เทคนิคอลอาร์ทิสต์','สะพานระหว่างศิลปินกับโปรแกรมเมอร์: เขียน shader ทำ VFX ปรับประสิทธิภาพงานภาพ และสร้างเครื่องมือช่วยทีม'),
('level_designer','นักออกแบบด่าน','ร่างแผนผังด่าน ทำ blockout ด้วยรูปทรงง่าย คุมจังหวะความตึงเครียด แล้วทดสอบกับผู้เล่นจริง'),
('game_audio_designer','นักออกแบบเสียงเกม','เสียงสร้างความรู้สึกครึ่งหนึ่งของเกม: สร้างเสียงประกอบ แต่งเพลง ใช้ middleware และเชื่อมเสียงกับเหตุการณ์ในเอนจิน'),
('xr_developer','นักพัฒนา VR/AR','ตั้งค่าโปรเจกต์ VR/AR ทำระบบหยิบจับที่รู้สึกเป็นธรรมชาติ ออกแบบไม่ให้ผู้ใช้เวียนหัว แล้วสร้างประสบการณ์สั้น ๆ'),
('3d_modeling','การสร้างโมเดล 3 มิติ','เรียนเครื่องมือ Blender สร้างโมเดลวัตถุหนึ่งชิ้น ใส่วัสดุ แล้วทำงานให้เสร็จสมบูรณ์พร้อมเรนเดอร์'),
('unity','Unity','ใช้ Unity Editor ให้คล่อง เขียนสคริปต์ C# ใช้ระบบฟิสิกส์และ UI แล้วรวมเป็นมินิเกมหนึ่งเกม'),
('unreal_engine','Unreal Engine','ฝึก Unreal Editor ต่อ logic ด้วย Blueprint ขยายด้วย C++ แล้วทำมินิเกมที่ใช้ทั้งสองอย่าง'),
('godot','Godot','เอนจินโอเพนซอร์สน้ำหนักเบา: เข้าใจระบบ node และ scene เขียน GDScript แล้วทำเกม 2D ได้ครบวงจร'),
('pixel_art','พิกเซลอาร์ต','ฝึกเส้นและรูปทรง เลือกจานสี วาดตัวละคร และทำแอนิเมชันพิกเซลที่มีชีวิต'),
('game_design','การออกแบบเกม','ออกแบบ core loop ฝึกในงาน game jam คุมเส้นความยาก และวิจารณ์งานออกแบบอย่างสร้างสรรค์')
insert into public.quest_definitions(id,goal_id,position,title,task,place,success,minutes,xp,coins) values
('ai_engineer.python_for_ai','ai_engineer','1','ฝึก Python สำหรับงาน AI','เขียน Python จัดการข้อมูล ฟังก์ชัน และไลบรารีที่ใช้บ่อยในงาน AI','หมู่บ้านเริ่มต้น','ทำ “ฝึก Python สำหรับงาน AI” ได้จริงอย่างน้อยหนึ่งครั้ง และอธิบายสิ่งที่เรียนรู้ด้วยคำพูดของตัวเองได้','25','80','60'),
('ai_engineer.call_llm_api','ai_engineer','2','เรียกใช้ LLM API','ส่งข้อความไปยังโมเดลภาษาผ่าน API แล้วนำคำตอบมาแสดงผล','ป่าของการเรียนรู้','ทำ “เรียกใช้ LLM API” ได้จริงอย่างน้อยหนึ่งครั้ง และอธิบายสิ่งที่เรียนรู้ด้วยคำพูดของตัวเองได้','25','100','90'),
('ai_engineer.prompt_design','ai_engineer','3','ออกแบบและทดสอบ prompt','เขียน prompt หลายแบบ เทียบผลลัพธ์ และจดว่าแบบไหนได้ผลดีที่สุด','ค่ายฝึก','ทำ “ออกแบบและทดสอบ prompt” ได้จริงอย่างน้อยหนึ่งครั้ง และอธิบายสิ่งที่เรียนรู้ด้วยคำพูดของตัวเองได้','25','120','120'),
('ai_engineer.build_rag','ai_engineer','4','สร้างระบบถามตอบจากเอกสาร','ทำ RAG ด้วย embedding และการค้นหาเอกสารมาประกอบคำตอบ','ปราสาทมืด','ทำ “สร้างระบบถามตอบจากเอกสาร” ได้จริงอย่างน้อยหนึ่งครั้ง และอธิบายสิ่งที่เรียนรู้ด้วยคำพูดของตัวเองได้','25','140','150'),
('ai_engineer.ai_mini_app','ai_engineer','5','โปรเจกต์แอป AI ขนาดเล็ก','สร้างแอปที่ใช้ AI แก้ปัญหาจริงหนึ่งอย่างให้คนอื่นลองใช้ได้','ยอดเขาจุดหมาย','ทำ “โปรเจกต์แอป AI ขนาดเล็ก” ได้จริงอย่างน้อยหนึ่งครั้ง และอธิบายสิ่งที่เรียนรู้ด้วยคำพูดของตัวเองได้','25','160','180'),
('ml_engineer.ml_math','ml_engineer','1','ทบทวนคณิตศาสตร์สำหรับ ML','ฝึกเวกเตอร์ เมทริกซ์ ความน่าจะเป็น และอนุพันธ์ที่ใช้ใน ML','หมู่บ้านเริ่มต้น','ทำ “ทบทวนคณิตศาสตร์สำหรับ ML” ได้จริงอย่างน้อยหนึ่งครั้ง และอธิบายสิ่งที่เรียนรู้ด้วยคำพูดของตัวเองได้','25','80','60'),
('ml_engineer.train_sklearn','ml_engineer','2','เทรนโมเดลด้วย scikit-learn','แบ่งข้อมูล train/test แล้วเทรนโมเดลจำแนกหรือทำนายค่า','ป่าของการเรียนรู้','ทำ “เทรนโมเดลด้วย scikit-learn” ได้จริงอย่างน้อยหนึ่งครั้ง และอธิบายสิ่งที่เรียนรู้ด้วยคำพูดของตัวเองได้','25','100','90'),
('ml_engineer.pytorch_basics','ml_engineer','3','ฝึก Deep Learning ด้วย PyTorch','สร้างโครงข่ายประสาทเทียมเล็ก ๆ และเทรนบนชุดข้อมูลตัวอย่าง','ค่ายฝึก','ทำ “ฝึก Deep Learning ด้วย PyTorch” ได้จริงอย่างน้อยหนึ่งครั้ง และอธิบายสิ่งที่เรียนรู้ด้วยคำพูดของตัวเองได้','25','120','120'),
('ml_engineer.evaluate_model','ml_engineer','4','วัดผลและปรับโมเดล','ใช้ accuracy, precision, recall และลองปรับ hyperparameter','ปราสาทมืด','ทำ “วัดผลและปรับโมเดล” ได้จริงอย่างน้อยหนึ่งครั้ง และอธิบายสิ่งที่เรียนรู้ด้วยคำพูดของตัวเองได้','25','140','150'),
('ml_engineer.deploy_model','ml_engineer','5','นำโมเดลขึ้นใช้งาน','ทำ API ให้โมเดลรับข้อมูลและตอบผลทำนายได้','ยอดเขาจุดหมาย','ทำ “นำโมเดลขึ้นใช้งาน” ได้จริงอย่างน้อยหนึ่งครั้ง และอธิบายสิ่งที่เรียนรู้ด้วยคำพูดของตัวเองได้','25','160','180'),
('data_scientist.practice_pandas','data_scientist','1','ฝึก pandas','โหลด ทำความสะอาด และสรุปข้อมูลตารางด้วย pandas','หมู่บ้านเริ่มต้น','ทำ “ฝึก pandas” ได้จริงอย่างน้อยหนึ่งครั้ง และอธิบายสิ่งที่เรียนรู้ด้วยคำพูดของตัวเองได้','25','80','60'),
('data_scientist.practice_sql','data_scientist','2','ฝึก SQL','เขียน query ดึง กรอง รวม และ join ข้อมูลจากฐานข้อมูล','ป่าของการเรียนรู้','ทำ “ฝึก SQL” ได้จริงอย่างน้อยหนึ่งครั้ง และอธิบายสิ่งที่เรียนรู้ด้วยคำพูดของตัวเองได้','25','100','90'),
('data_scientist.visualize_data','data_scientist','3','สร้างกราฟจากข้อมูล','ใช้ matplotlib หรือเครื่องมืออื่นทำกราฟที่เล่าเรื่องได้ชัด','ค่ายฝึก','ทำ “สร้างกราฟจากข้อมูล” ได้จริงอย่างน้อยหนึ่งครั้ง และอธิบายสิ่งที่เรียนรู้ด้วยคำพูดของตัวเองได้','25','120','120'),
