insert into public.user_goals(user_id,goal_id,started_at,completed_at,active_quest_id)
 insert into public.profiles(user_id) values (u) on conflict do nothing;
 insert into public.user_progress(user_id) values (u) on conflict do nothing;
   insert into public.plan_items(id,user_id,plan_day,start_time,minutes,kind,ref,note,done)
  insert into public.quest_progress(user_id,quest_id,status) select u,id,case when position=1 then 'available' else 'locked' end from public.quest_definitions where goal_id=gid;
  insert into public.user_goals(user_id,goal_id,started_at) values(u,gid,at_time);
   insert into public.quest_evidence(id,user_id,quest_id,path,mime,size) values((payload->>'id')::uuid,u,q.id,payload->>'path',payload->>'mime',(payload->>'size')::integer)
   insert into public.focus_sessions(user_id,quest_id,status,duration_ms,started_at,created_at) values(u,q.id,'running',q.minutes*60000,at_time,at_time);
  insert into public.reward_ledger(user_id,quest_id,attempt,completed_at,xp,coins,total_xp_before)
