-- Multi-goal adventures and daily plans (generated by scripts/generate-goals-migration.mjs).
-- Every career/skill path becomes a goal with its own map; players add several goals and may abandon one, which
-- clears that goal's map progress (quests, checklist, focus, bosses, photos) but keeps earned XP and coins.
-- A quest completed again after abandoning pays XP only (coins once per quest). Existing progress is preserved:
-- players who had selected "first-game" keep it as an added goal with every reward, focus round and boss win.
-- plan_items stores the calendar: focus time slots per day.

on conflict (id) do nothing;
on conflict (id) do nothing;
on conflict (quest_id,id) do nothing;
on conflict (id) do nothing;
on conflict (question_id) do nothing;

-- Rewards outlive quest progress: the ledger no longer cascades from quest_progress and records attempts.
do $$ declare c record; begin
 for c in select conname from pg_constraint where conrelid='public.reward_ledger'::regclass and contype='f' and confrelid='public.quest_progress'::regclass loop
  execute format('alter table public.reward_ledger drop constraint %I',c.conname); end loop;
end $$;
alter table public.reward_ledger add column attempt integer not null default 1 check(attempt>0);
alter table public.reward_ledger drop constraint reward_ledger_pkey;
alter table public.reward_ledger add primary key(user_id,quest_id,attempt),
 add constraint reward_ledger_user_fk foreign key(user_id) references public.user_progress(user_id) on delete cascade,
 add constraint reward_ledger_quest_fk foreign key(quest_id) references public.quest_definitions(id);
create index reward_ledger_quest_idx on public.reward_ledger(quest_id);

-- One active quest per goal (not per user). One running focus round per user is still enforced.
drop index public.one_active_quest_per_user;
create table public.user_goals(
 user_id uuid not null references public.user_progress(user_id) on delete cascade,
 goal_id text not null references public.journey_definitions(id),
 started_at timestamptz not null default clock_timestamp(),
 completed_at timestamptz,
 active_quest_id text references public.quest_definitions(id),
 primary key(user_id,goal_id),
 check(completed_at is null or active_quest_id is null)
);
alter table public.user_goals add constraint user_goals_active_owned foreign key(user_id,active_quest_id)
 references public.quest_progress(user_id,quest_id) deferrable initially deferred;
create index user_goals_goal_idx on public.user_goals(goal_id);
create index user_goals_active_idx on public.user_goals(active_quest_id);
alter table public.user_goals enable row level security;
revoke all on public.user_goals from public,anon,authenticated;
grant select on public.user_goals to authenticated;
create policy own_goals_read on public.user_goals for select to authenticated using((select auth.uid())=user_id);

-- Daily plan: focus time slots on calendar days (a goal quest, a practice task "career|task", or a free-text note).
create table public.plan_items(
 id uuid primary key,
 user_id uuid not null references public.user_progress(user_id) on delete cascade,
 plan_day date not null, start_time time not null,
 minutes integer not null check(minutes between 5 and 240),
 kind text not null check(kind in ('quest','practice','note')),
 ref text not null default '', note text not null default '' check(char_length(note)<=80),
 done boolean not null default false,
 created_at timestamptz not null default clock_timestamp()
);
create index plan_items_user_day_idx on public.plan_items(user_id,plan_day);
alter table public.plan_items enable row level security;
revoke all on public.plan_items from public,anon,authenticated;
grant select on public.plan_items to authenticated;
create policy own_plans_read on public.plan_items for select to authenticated using((select auth.uid())=user_id);

 select p.user_id,'first-game',coalesce((select min(l.completed_at) from public.reward_ledger l where l.user_id=p.user_id),clock_timestamp()),p.goal_completed_at,p.active_quest_id
 from public.user_progress p where p.selected_goal_id='first-game';
update public.user_progress set selected_goal_id=null,active_quest_id=null,goal_completed_at=null,revision=revision+1;
-- Players who never chose a goal only had untouched first-game rows (seeded at sign-up); remove them.
delete from public.quest_progress x where not exists(select 1 from public.user_goals g join public.quest_definitions d on d.goal_id=g.goal_id where g.user_id=x.user_id and d.id=x.quest_id);

-- Sign-up no longer seeds a map; adding a goal does.
create or replace function private.ensure_user() returns uuid language plpgsql security invoker set search_path = '' as $$
declare u uuid := auth.uid();
begin
 if u is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
 if not exists (select 1 from public.journey_definitions where id = 'first-game') then raise exception 'DEFINITIONS_MISSING'; end if;
 perform 1 from public.user_progress where user_id = u for update;
 return u;
end $$;

alter function private.snapshot() rename to snapshot_v7;
revoke all on function private.snapshot_v7() from public,anon,authenticated;
create function private.snapshot() returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid; at_time timestamptz; p public.user_progress; quest public.quest_definitions; f jsonb:='{}'::jsonb; s public.focus_sessions;
 checked jsonb; focus_ms bigint; rounds jsonb; goals jsonb; quests jsonb; rewards jsonb; bosses jsonb; photos jsonb; practice jsonb; skins jsonb; buys jsonb; uses jsonb; plans jsonb; xp_sum bigint;
begin
 u:=private.ensure_user(); at_time:=clock_timestamp();
 perform private.settle_session(u,at_time);
 select * into p from public.user_progress where user_id=u;
 for quest in select d.* from public.quest_definitions d join public.user_goals g on g.goal_id=d.goal_id and g.user_id=u order by d.goal_id,d.position loop
   select coalesce(jsonb_agg(c.step_id order by t.position),'[]'::jsonb) into checked from public.checklist c
    join public.quest_steps t on t.quest_id=c.quest_id and t.id=c.step_id where c.user_id=u and c.quest_id=quest.id;
   select coalesce(sum(elapsed_ms),0) into focus_ms from public.focus_sessions where user_id=u and quest_id=quest.id;
   select * into s from public.focus_sessions where user_id=u and quest_id=quest.id order by created_at desc,id desc limit 1;
   if not found then rounds:=jsonb_build_object('status','idle','durationMs',quest.minutes*60000,'elapsedMs',0,'startedAt',null);
   else rounds:=jsonb_build_object('status',case when s.status='closed' then case when s.elapsed_ms=s.duration_ms then 'finished' else 'paused' end else s.status end,
    'durationMs',s.duration_ms,'elapsedMs',s.elapsed_ms,'startedAt',case when s.started_at is null then null else floor(extract(epoch from s.started_at)*1000)::bigint end); end if;
   f:=f||jsonb_build_object(quest.id,jsonb_build_object('checkedStepIds',checked,'totalMs',focus_ms,'round',rounds));
 end loop;
 select coalesce(jsonb_object_agg(goal_id,jsonb_build_object('startedAt',floor(extract(epoch from started_at)*1000)::bigint,'completedAt',case when completed_at is null then null else floor(extract(epoch from completed_at)*1000)::bigint end,'activeQuestId',active_quest_id)),'{}'::jsonb)
  into goals from public.user_goals where user_id=u;
 select coalesce(jsonb_object_agg(x.quest_id,x.status),'{}'::jsonb) into quests from public.quest_progress x
  join public.quest_definitions d on d.id=x.quest_id join public.user_goals g on g.user_id=x.user_id and g.goal_id=d.goal_id where x.user_id=u;
 select coalesce(jsonb_agg(jsonb_build_object('questId',l.quest_id,'goalId',d.goal_id,'attempt',l.attempt,'completedAt',floor(extract(epoch from l.completed_at)*1000)::bigint,'xp',l.xp,'coins',l.coins,'totalXPBefore',l.total_xp_before) order by l.total_xp_before,l.completed_at,l.quest_id),'[]'::jsonb),coalesce(sum(l.xp),0)
  into rewards,xp_sum from public.reward_ledger l join public.quest_definitions d on d.id=l.quest_id where l.user_id=u;
 select coalesce(jsonb_object_agg(quest_id,jsonb_build_object('score',score,'total',total,'attempts',attempts,'passedAt',case when passed_at is null then null else floor(extract(epoch from passed_at)*1000)::bigint end)),'{}'::jsonb)
  into bosses from public.boss_results where user_id=u;
 select coalesce(jsonb_object_agg(quest_id,jsonb_build_object('id',id,'questId',quest_id,'path',path,'mime',mime,'size',size,'createdAt',floor(extract(epoch from created_at)*1000)::bigint)),'{}'::jsonb)
  into photos from public.quest_evidence where user_id=u;
 select coalesce(jsonb_object_agg(to_char(practice_day,'YYYY-MM-DD')||'|'||career_id||'|'||task_id,jsonb_build_object('careerId',career_id,'taskId',task_id,'day',to_char(practice_day,'YYYY-MM-DD'),'completedAt',floor(extract(epoch from completed_at)*1000)::bigint,'xp',xp,'coins',coins)),'{}'::jsonb),xp_sum+coalesce(sum(xp),0)
  into practice,xp_sum from public.practice_log where user_id=u;
 select coalesce(jsonb_object_agg(skin_id,jsonb_build_object('skinId',skin_id,'coins',coins,'purchasedAt',floor(extract(epoch from purchased_at)*1000)::bigint)),'{}'::jsonb) into skins from public.skin_purchases where user_id=u;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'itemId',item_id,'qty',qty,'coins',coins,'purchasedAt',floor(extract(epoch from purchased_at)*1000)::bigint) order by purchased_at,id),'[]'::jsonb) into buys from public.item_purchases where user_id=u;
 select coalesce(jsonb_agg(jsonb_build_object('itemId',item_id,'questId',quest_id,'battleId',battle_id,'usedAt',floor(extract(epoch from used_at)*1000)::bigint) order by used_at,id),'[]'::jsonb) into uses from public.item_uses where user_id=u;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'day',to_char(plan_day,'YYYY-MM-DD'),'start',to_char(start_time,'HH24:MI'),'minutes',minutes,'kind',kind,'ref',ref,'note',note,'done',done) order by plan_day,start_time,id),'[]'::jsonb)
  into plans from public.plan_items where user_id=u;
 return jsonb_build_object('userId',u,'characterName',(select character_name from public.profiles where user_id=u),'revision',p.revision,'serverNow',floor(extract(epoch from at_time)*1000)::bigint,
  'progress',jsonb_build_object('version',8,'goals',goals,'quests',quests,'focus',f,'rewards',rewards,'bosses',bosses,'evidence',photos,'practice',practice,
   'careerId',p.career_id,'equippedSkinId',p.equipped_skin_id,'skins',skins,'itemPurchases',buys,'itemUses',uses,'plans',plans,'totalXP',xp_sum,'coins',private.funds(u)));
end $$;
revoke all on function private.snapshot() from public,anon,authenticated;
grant execute on function private.snapshot() to authenticated;
create or replace function public.liferpg_snapshot() returns jsonb language sql security invoker set search_path='' as $$select private.snapshot();$$;

-- Goal, quest and plan actions are handled here for any goal; shop, practice and career choice keep their existing rules.
create function private.goal_command(action text,payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid; at_time timestamptz; g public.user_goals; q public.quest_definitions; qp public.quest_progress; s public.focus_sessions; used bigint; next_id text;
 gid text:=payload->>'goalId'; ids text[]; on_day date; d integer; h integer; score integer; total integer; battle uuid; answers jsonb:=payload->'answers';
begin
 if action in ('select_career','buy_skin','equip_skin','buy_item','practice','purchase','equip') then return private.shop_command(action,payload); end if;
 u:=private.ensure_user(); at_time:=clock_timestamp(); -- row lock serialises every write of this player
 if action in ('plan_add','plan_remove','plan_done') then
  if coalesce(payload->>'id','')!~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then raise exception 'PLAN_INVALID'; end if;
  if action='plan_add' then
   if exists(select 1 from public.plan_items where id=(payload->>'id')::uuid) then
    if exists(select 1 from public.plan_items where id=(payload->>'id')::uuid and user_id=u) then return private.snapshot(); end if;
    raise exception 'PLAN_INVALID';
   end if;
   if coalesce(payload->>'day','')!~'^20[2-9][0-9]-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' or coalesce(payload->>'start','')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$'
    or jsonb_typeof(payload->'minutes') is distinct from 'number' or (payload->>'minutes')!~'^[0-9]{1,3}$' or (payload->>'minutes')::integer not between 5 and 240
    or coalesce(payload->>'kind','') not in ('quest','practice','note') or jsonb_typeof(payload->'ref') is distinct from 'string' or jsonb_typeof(payload->'note') is distinct from 'string'
    or char_length(payload->>'note')>80 or jsonb_typeof(payload->'done') is distinct from 'boolean' then raise exception 'PLAN_INVALID'; end if;
   begin on_day:=(payload->>'day')::date; exception when others then raise exception 'PLAN_INVALID'; end;
   if to_char(on_day,'YYYY-MM-DD')<>payload->>'day'
    or (payload->>'kind'='quest' and not exists(select 1 from public.quest_definitions where id=payload->>'ref'))
    or (payload->>'kind'='practice' and not exists(select 1 from public.career_tasks where career_id||'|'||id=payload->>'ref'))
    or (payload->>'kind'='note' and (payload->>'ref'<>'' or btrim(payload->>'note')='')) then raise exception 'PLAN_INVALID'; end if;
   if (select count(*) from public.plan_items where user_id=u and plan_day=on_day)>=12 or (select count(*) from public.plan_items where user_id=u)>=500 then raise exception 'PLAN_LIMIT'; end if;
    values((payload->>'id')::uuid,u,on_day,(payload->>'start')::time,(payload->>'minutes')::integer,payload->>'kind',payload->>'ref',payload->>'note',(payload->>'done')::boolean);
  elsif action='plan_remove' then delete from public.plan_items where user_id=u and id=(payload->>'id')::uuid;
  else
   if jsonb_typeof(payload->'done') is distinct from 'boolean' then raise exception 'PLAN_INVALID'; end if;
   update public.plan_items set done=(payload->>'done')::boolean where user_id=u and id=(payload->>'id')::uuid;
   if not found then raise exception 'PLAN_INVALID'; end if;
  end if;
  update public.user_progress set revision=revision+1 where user_id=u;
  return private.snapshot();
 end if;
 if action in ('add_goal','select') then
  if gid is null or not exists(select 1 from public.journey_definitions where id=gid) then raise exception 'GOAL_INVALID'; end if;
  if exists(select 1 from public.user_goals where user_id=u and goal_id=gid) then return private.snapshot(); end if;
  ids:=array(select id from public.quest_definitions where goal_id=gid);
  delete from public.boss_results where user_id=u and quest_id=any(ids);
  delete from public.quest_evidence where user_id=u and quest_id=any(ids);
  delete from public.quest_progress where user_id=u and quest_id=any(ids);
  update public.user_progress set revision=revision+1 where user_id=u;
  return private.snapshot();
 end if;
 if action='abandon_goal' then
  if not exists(select 1 from public.user_goals where user_id=u and goal_id=gid) then raise exception 'GOAL_NOT_ADDED'; end if;
  ids:=array(select id from public.quest_definitions where goal_id=gid);
  delete from public.user_goals where user_id=u and goal_id=gid;
  delete from public.boss_results where user_id=u and quest_id=any(ids);
  delete from public.quest_evidence where user_id=u and quest_id=any(ids);
  delete from public.quest_progress where user_id=u and quest_id=any(ids); -- cascades checklist and focus sessions; ledger stays
  update public.user_progress set revision=revision+1 where user_id=u;
  return private.snapshot();
 end if;
 select * into q from public.quest_definitions where id=payload->>'questId';
 if not found then raise exception 'QUEST_INVALID'; end if;
 select * into g from public.user_goals where user_id=u and goal_id=q.goal_id;
 if not found then raise exception 'GOAL_NOT_ADDED'; end if;
 select * into qp from public.quest_progress where user_id=u and quest_id=q.id;
 if action in ('evidence_add','evidence_remove') then
  if qp.status is null or qp.status not in ('in_progress','completed') then raise exception 'QUEST_UNAVAILABLE'; end if;
  if action='evidence_remove' then delete from public.quest_evidence where user_id=u and quest_id=q.id;
  else
   if payload->>'path'<>u::text||'/'||q.id||'/'||(payload->>'id')||'.jpg' then raise exception 'EVIDENCE_PATH_INVALID'; end if;
   if not exists(select 1 from storage.objects where bucket_id='quest-evidence' and name=payload->>'path') then raise exception 'EVIDENCE_FILE_MISSING'; end if;
    on conflict(user_id,quest_id) do update set id=excluded.id,path=excluded.path,mime=excluded.mime,size=excluded.size,created_at=clock_timestamp();
  end if;
  update public.user_progress set revision=revision+1 where user_id=u;
  return private.snapshot();
 end if;
 if action in ('complete','finish') and qp.status='completed' then return private.snapshot(); end if;
 if action='start_quest' then
  if qp.status='in_progress' and g.active_quest_id=q.id then return private.snapshot(); end if;
  if g.active_quest_id is not null or qp.status is distinct from 'available' then raise exception 'QUEST_UNAVAILABLE'; end if;
  if exists(select 1 from public.quest_definitions x join public.quest_progress y on y.quest_id=x.id and y.user_id=u where x.goal_id=q.goal_id and x.position<q.position and y.status<>'completed') then raise exception 'QUEST_LOCKED'; end if;
  update public.quest_progress set status='in_progress' where user_id=u and quest_id=q.id;
  update public.user_goals set active_quest_id=q.id where user_id=u and goal_id=q.goal_id;
  update public.user_progress set revision=revision+1 where user_id=u;
  return private.snapshot();
 end if;
 if g.active_quest_id is distinct from q.id or qp.status is distinct from 'in_progress' then raise exception 'QUEST_NOT_ACTIVE'; end if;
 if action='check' then
  if not exists(select 1 from public.quest_steps where quest_id=q.id and id=payload->>'stepId') or jsonb_typeof(payload->'checked') is distinct from 'boolean' then raise exception 'STEP_INVALID'; end if;
  if (payload->>'checked')::boolean then insert into public.checklist(user_id,quest_id,step_id) values(u,q.id,payload->>'stepId') on conflict do nothing;
  else delete from public.checklist where user_id=u and quest_id=q.id and step_id=payload->>'stepId'; end if;
 elsif action in ('start','pause','resume','new','finish') then
  perform private.settle_session(u,at_time);
  if action in ('start','resume','new') then -- one timer at a time: pause another quest's running round
   select * into s from public.focus_sessions where user_id=u and status='running' and quest_id<>q.id for update;
   if found then
    used:=least(s.duration_ms-s.elapsed_ms,greatest(0,floor(extract(epoch from (at_time-s.started_at))*1000)::bigint));
    update public.focus_sessions set status='paused',elapsed_ms=s.elapsed_ms+used,started_at=null where id=s.id;
   end if;
  end if;
  select * into s from public.focus_sessions where user_id=u and quest_id=q.id order by created_at desc,id desc limit 1 for update;
  if (action='start' and s.id is null) or (action='new' and s.status='finished') then
  elsif action='pause' and s.status='running' then
   used:=least(s.duration_ms-s.elapsed_ms,greatest(0,floor(extract(epoch from (at_time-s.started_at))*1000)::bigint));
   update public.focus_sessions set status='paused',elapsed_ms=s.elapsed_ms+used,started_at=null where id=s.id;
  elsif action='resume' and s.status='paused' then update public.focus_sessions set status='running',started_at=at_time where id=s.id;
  end if;
 elsif action='complete' then
  if exists(select 1 from public.quest_steps t where t.quest_id=q.id and not exists(select 1 from public.checklist c where c.user_id=u and c.quest_id=q.id and c.step_id=t.id)) then raise exception 'CHECKLIST_INCOMPLETE'; end if;
  if not exists(select 1 from public.boss_results where user_id=u and quest_id=q.id and passed_at is not null) then raise exception 'BOSS_REQUIRED'; end if;
  perform private.settle_session(u,at_time);
  select * into s from public.focus_sessions where user_id=u and quest_id=q.id and status='running' for update;
  if found then -- close this quest's round at the confirmation time
   used:=least(s.duration_ms-s.elapsed_ms,greatest(0,floor(extract(epoch from (at_time-s.started_at))*1000)::bigint));
   update public.focus_sessions set status='closed',elapsed_ms=s.elapsed_ms+used,started_at=null where id=s.id;
  end if;
   values(u,q.id,coalesce((select max(attempt) from public.reward_ledger where user_id=u and quest_id=q.id),0)+1,at_time,q.xp,
    case when exists(select 1 from public.reward_ledger where user_id=u and quest_id=q.id) then 0 else q.coins end,
    (select coalesce(sum(xp),0) from public.reward_ledger where user_id=u));
  update public.quest_progress set status='completed',completed_at=at_time where user_id=u and quest_id=q.id;
  select id into next_id from public.quest_definitions where goal_id=q.goal_id and position=q.position+1;
  update public.user_goals set active_quest_id=null,completed_at=case when next_id is null then at_time else null end where user_id=u and goal_id=q.goal_id;
  if next_id is not null then update public.quest_progress set status='available' where user_id=u and quest_id=next_id and status='locked'; end if;
 elsif action in ('boss_attempt','use_item') then
  if coalesce(payload->>'battleId','')!~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
   if action='use_item' then raise exception 'BATTLE_INVALID'; end if; battle:=null; else battle:=(payload->>'battleId')::uuid; end if;
  if action='use_item' then
   if not exists(select 1 from public.item_catalog where id=payload->>'itemId') then raise exception 'ITEM_INVALID'; end if;
   if private.stock(u,payload->>'itemId')<1 then raise exception 'ITEM_OUT_OF_STOCK'; end if;
  else
   -- every answered question must be right; x2 potions drunk in this fight let fewer answers win
   if exists(select 1 from public.quest_steps t where t.quest_id=q.id and not exists(select 1 from public.checklist c where c.user_id=u and c.quest_id=q.id and c.step_id=t.id)) then raise exception 'CHECKLIST_INCOMPLETE'; end if;
   if exists(select 1 from public.boss_results where user_id=u and quest_id=q.id and passed_at is not null) then return private.snapshot(); end if;
   select count(*) into total from public.boss_questions where quest_id=q.id;
   d:=case when battle is null then 0 else (select count(*) from public.item_uses where user_id=u and quest_id=q.id and battle_id=battle and item_id='double') end;
   if total=0 or jsonb_typeof(answers) is distinct from 'object' then raise exception 'BOSS_ANSWERS_INVALID'; end if;
   select count(*) into h from jsonb_object_keys(answers);
   if h<1 or h>total or (d=0 and h<>total) or exists(select 1 from jsonb_object_keys(answers) k where not exists(select 1 from public.boss_questions b where b.quest_id=q.id and b.id=k))
    or exists(select 1 from public.boss_questions b where b.quest_id=q.id and answers ? b.id and (jsonb_typeof(answers->b.id) is distinct from 'number' or (answers->>b.id)!~'^[0-9]$' or (answers->>b.id)::integer>=jsonb_array_length(b.options))) then raise exception 'BOSS_ANSWERS_INVALID'; end if;
   select count(*) into score from public.boss_questions b join private.boss_answers a on a.question_id=b.id where b.quest_id=q.id and answers ? b.id and (answers->>b.id)::integer=a.answer;
   if score=h and score+least(d,score)>=total then score:=total; else score:=least(score,total-1); end if;
    on conflict(user_id,quest_id) do update set score=excluded.score,total=excluded.total,attempts=public.boss_results.attempts+1,passed_at=excluded.passed_at;
  end if;
 else raise exception 'ACTION_INVALID'; end if;
 update public.user_progress set revision=revision+1 where user_id=u;
 return private.snapshot();
end $$;
revoke all on function private.goal_command(text,jsonb) from public,anon,authenticated;
grant execute on function private.goal_command(text,jsonb) to authenticated;
create or replace function public.liferpg_command(action text,payload jsonb) returns jsonb language sql security invoker set search_path='' as $$select private.goal_command(action,payload);$$;
